# WAR — live token search bar (uses /search): type name or paste address
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-search-bar.ps1
$ErrorActionPreference = "Stop"
if (-not (Test-Path "miniapp")) { Write-Host "ERROR: run from project root" -ForegroundColor Red; exit 1 }
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "miniapp\index.html"), [Convert]::FromBase64String($b64))
Write-Host "  wrote miniapp/index.html" -ForegroundColor Green
Write-Host "Then: git add -A; git commit -m search-bar; git push" -ForegroundColor Cyan